resource "azurerm_resource_group" "northbridge" {
  name     = "rg-northbridge-prod"
  location = "eastus2"
}

resource "azurerm_storage_account" "images" {
  name                     = "northbridgeprodimages"
  resource_group_name      = azurerm_resource_group.northbridge.name
  location                 = azurerm_resource_group.northbridge.location
  account_tier             = "Standard"
  account_replication_type = "GRS"
}

resource "azurerm_linux_function_app" "pipeline" {
  name                       = "func-nbretail-pipeline-dev"
  storage_account_name       = module.storage_dev.storage_account_name
  storage_account_access_key = module.storage_dev.primary_access_key
  service_plan_id            = azurerm_service_plan.dev.id
}

resource "azurerm_kubernetes_cluster" "checkout" {
  default_node_pool {
    name       = "default"
    node_count = 3
    vm_size    = "Standard_D4s_v5"
  }

  identity {
    type = "SystemAssigned"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.northbridge.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.northbridge.id
  }
}

resource "aws_route_table_association" "order_processing" {
  subnet_id      = aws_subnet.order_processing.id
  route_table_id = aws_route_table.public.id
}
